import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { StaleWhileRevalidate, CacheFirst, NetworkFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

// 安全验证（预留后续补充，如消息源校验等）

// Precache all assets generated by build
precacheAndRoute(self.__WB_MANIFEST);

// 消息通道：workbox-window / 手动注册逻辑通过 postMessage({ type: 'SKIP_WAITING' })
// 请求新 SW 立即接管；registerType: 'autoUpdate' 下这是预期行为
self.addEventListener('message', event => {
  // 只处理来自可信来源（同源页面/客户端）的消息
  if (event.origin === self.location.origin && event.data?.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// 1. 字体缓存 (CacheFirst) - 极少变动
registerRoute(
  ({ request }) => request.destination === 'font',
  new CacheFirst({
    cacheName: 'wotech-font-cache-v1',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 20,
        maxAgeSeconds: 60 * 60 * 24 * 365, // 1 Year
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200], // 0 for opaque responses
      }),
    ],
  })
);

// 2. 图片缓存 (StaleWhileRevalidate) - 兼顾性能与更新
registerRoute(
  ({ request }) => request.destination === 'image',
  new StaleWhileRevalidate({
    cacheName: 'wotech-image-cache-v1',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 60 * 60 * 24 * 30, // 30 Days
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  })
);

// 3. 页面文档 (NetworkFirst) - 确保内容最新，离线时回退到缓存
registerRoute(
  ({ request }) => request.mode === 'navigate',
  new NetworkFirst({
    cacheName: 'wotech-pages-cache-v1',
    plugins: [
      new CacheableResponsePlugin({
        statuses: [200],
      }),
    ],
  })
);

// 4. CSS/JS 资源 (StaleWhileRevalidate)
registerRoute(
  ({ request }) => request.destination === 'script' || request.destination === 'style',
  new StaleWhileRevalidate({
    cacheName: 'wotech-static-cache-v1',
    plugins: [
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  })
);

// 5. 安全清理：定期清理过期缓存；skipWaiting 让新 SW 跳过等待直接激活，
// clients.claim 让激活后立即接管已开标签页——两者配合实现 autoUpdate 真正的"自动更新"
// （injectManifest 模式下 vite-plugin-pwa 不会注入 skipWaiting，必须手写）
self.addEventListener('activate', event => {
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      await Promise.all(
        cacheNames.map(cacheName => {
          // 只保留当前版本的 wotech-* 缓存
          if (cacheName.startsWith('wotech-') && !cacheName.includes('-v1')) {
            return caches.delete(cacheName);
          }
          return undefined;
        })
      );
      await self.clients.claim();
    })()
  );
});
self.skipWaiting();
